B.agf=new A.n(B.at,["\u0410\u043d\u0430\u043b\u0438\u0437\u044b","\u041b\u0435\u043a\u0430\u0440\u0441\u0442\u0432\u0430","\u0421\u0444\u043e\u0442\u043e\u0433\u0440\u0430\u0444\u0438\u0440\u0443\u0439\u0442\u0435 \u043b\u0430\u0431\u043e\u0440\u0430\u0442\u043e\u0440\u043d\u044b\u0439 \u0431\u043b\u0430\u043d\u043a \u0446\u0435\u043b\u0438\u043a\u043e\u043c \u043f\u0440\u0438 \u0445\u043e\u0440\u043e\u0448\u0435\u043c \u043e\u0441\u0432\u0435\u0449\u0435\u043d\u0438\u0438. \u041f\u043e \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e\u0441\u0442\u0438 \u0437\u0430\u043a\u0440\u043e\u0439\u0442\u0435 \u0424\u0418\u041e \u0438 \u0434\u0440\u0443\u0433\u0438\u0435 \u043f\u0435\u0440\u0441\u043e\u043d\u0430\u043b\u044c\u043d\u044b\u0435 \u0434\u0430\u043d\u043d\u044b\u0435.","\u041e\u0431\u044a\u044f\u0441\u043d\u0438\u0442\u044c \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u044b","\u041b\u0435\u043a\u0430\u0440\u0441\u0442\u0432\u0430 \u0438 \u0434\u043e\u0437\u0438\u0440\u043e\u0432\u043a\u0438","\u041d\u0430\u043f\u0440\u0438\u043c\u0435\u0440: \u043c\u0435\u0442\u0444\u043e\u0440\u043c\u0438\u043d 500 \u043c\u0433, \u044d\u043d\u0430\u043b\u0430\u043f\u0440\u0438\u043b 10 \u043c\u0433...","\u0414\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u043e","\u0410\u043b\u043b\u0435\u0440\u0433\u0438\u0438, \u0431\u043e\u043b\u0435\u0437\u043d\u0438 \u043f\u043e\u0447\u0435\u043a/\u043f\u0435\u0447\u0435\u043d\u0438, \u0431\u0435\u0440\u0435\u043c\u0435\u043d\u043d\u043e\u0441\u0442\u044c...","\u041f\u0440\u043e\u0432\u0435\u0440\u0438\u0442\u044c \u0441\u043e\u0432\u043c\u0435\u0441\u0442\u0438\u043c\u043e\u0441\u0442\u044c","\u0412\u0430\u0436\u043d\u043e: AI \u043c\u043e\u0436\u0435\u0442 \u043e\u0448\u0438\u0431\u0430\u0442\u044c\u0441\u044f. \u042d\u0442\u043e \u043d\u0435 \u0434\u0438\u0430\u0433\u043d\u043e\u0437 \u0438 \u043d\u0435 \u043d\u0430\u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u043b\u0435\u0447\u0435\u043d\u0438\u044f. \u041d\u0435 \u043c\u0435\u043d\u044f\u0439\u0442\u0435 \u043b\u0435\u043a\u0430\u0440\u0441\u0442\u0432\u0430 \u0438\u043b\u0438 \u0434\u043e\u0437\u044b \u0431\u0435\u0437 \u0432\u0440\u0430\u0447\u0430. \u041f\u0440\u0438 \u043e\u043f\u0430\u0441\u043d\u044b\u0445 \u0441\u0438\u043c\u043f\u0442\u043e\u043c\u0430\u0445 \u0437\u0432\u043e\u043d\u0438\u0442\u0435 112.","\u0424\u043e\u0442\u043e \u0430\u043d\u0430\u043b\u0438\u0437\u0430 \u043f\u043e\u044f\u0432\u0438\u0442\u0441\u044f \u0437\u0434\u0435\u0441\u044c"],t.w)
B.ag_=new A.n(B.at,["\u0410\u043d\u0430\u043b\u0456\u0437\u0438","\u041b\u0456\u043a\u0438","\u0421\u0444\u043e\u0442\u043e\u0433\u0440\u0430\u0444\u0443\u0439\u0442\u0435 \u043b\u0430\u0431\u043e\u0440\u0430\u0442\u043e\u0440\u043d\u0438\u0439 \u0431\u043b\u0430\u043d\u043a \u043f\u043e\u0432\u043d\u0456\u0441\u0442\u044e \u043f\u0440\u0438 \u0445\u043e\u0440\u043e\u0448\u043e\u043c\u0443 \u043e\u0441\u0432\u0456\u0442\u043b\u0435\u043d\u043d\u0456. \u0417\u0430 \u043c\u043e\u0436\u043b\u0438\u0432\u043e\u0441\u0442\u0456 \u0437\u0430\u043a\u0440\u0438\u0439\u0442\u0435 \u041f\u0406\u0411 \u0442\u0430 \u0456\u043d\u0448\u0456 \u043f\u0435\u0440\u0441\u043e\u043d\u0430\u043b\u044c\u043d\u0456 \u0434\u0430\u043d\u0456.","\u041f\u043e\u044f\u0441\u043d\u0438\u0442\u0438 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0438","\u041b\u0456\u043a\u0438 \u0442\u0430 \u0434\u043e\u0437\u0443\u0432\u0430\u043d\u043d\u044f","\u041d\u0430\u043f\u0440\u0438\u043a\u043b\u0430\u0434: \u043c\u0435\u0442\u0444\u043e\u0440\u043c\u0456\u043d 500 \u043c\u0433, \u0435\u043d\u0430\u043b\u0430\u043f\u0440\u0438\u043b 10 \u043c\u0433...","\u0414\u043e\u0434\u0430\u0442\u043a\u043e\u0432\u043e","\u0410\u043b\u0435\u0440\u0433\u0456\u0457, \u0445\u0432\u043e\u0440\u043e\u0431\u0438 \u043d\u0438\u0440\u043e\u043a/\u043f\u0435\u0447\u0456\u043d\u043a\u0438, \u0432\u0430\u0433\u0456\u0442\u043d\u0456\u0441\u0442\u044c...","\u041f\u0435\u0440\u0435\u0432\u0456\u0440\u0438\u0442\u0438 \u0441\u0443\u043c\u0456\u0441\u043d\u0456\u0441\u0442\u044c","\u0412\u0430\u0436\u043b\u0438\u0432\u043e: AI \u043c\u043e\u0436\u0435 \u043f\u043e\u043c\u0438\u043b\u044f\u0442\u0438\u0441\u044f. \u0426\u0435 \u043d\u0435 \u0434\u0456\u0430\u0433\u043d\u043e\u0437 \u0456 \u043d\u0435 \u043f\u0440\u0438\u0437\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u043b\u0456\u043a\u0443\u0432\u0430\u043d\u043d\u044f. \u041d\u0435 \u0437\u043c\u0456\u043d\u044e\u0439\u0442\u0435 \u043b\u0456\u043a\u0438 \u0430\u0431\u043e \u0434\u043e\u0437\u0438 \u0431\u0435\u0437 \u043b\u0456\u043a\u0430\u0440\u044f. \u041f\u0440\u0438 \u043d\u0435\u0431\u0435\u0437\u043f\u0435\u0447\u043d\u0438\u0445 \u0441\u0438\u043c\u043f\u0442\u043e\u043c\u0430\u0445 \u0442\u0435\u043b\u0435\u0444\u043e\u043d\u0443\u0439\u0442\u0435 112.","\u0424\u043e\u0442\u043e \u0430\u043d\u0430\u043b\u0456\u0437\u0443 \u0437\u2019\u044f\u0432\u0438\u0442\u044c\u0441\u044f \u0442\u0443\u0442"],t.w)
B.age=new A.n(B.at,["Laborwerte","Medikamente","Fotografieren Sie den gesamten Laborbericht bei gutem Licht. Verdecken Sie m\xf6glichst Name und pers\xf6nliche Daten.","Ergebnisse erkl\xe4ren","Medikamente und Dosierungen","Beispiel: Metformin 500 mg, Enalapril 10 mg...","Zus\xe4tzlich","Allergien, Nieren-/Lebererkrankungen, Schwangerschaft...","Vertr\xe4glichkeit pr\xfcfen","Wichtig: AI kann Fehler machen. Dies ist keine Diagnose und keine Behandlungsempfehlung. \xc4ndern Sie Medikamente oder Dosen nicht ohne Arzt. Bei gef\xe4hrlichen Symptomen rufen Sie den Notdienst.","Laborfoto erscheint hier"],t.w)
B.agj=new A.n(B.at,["Analyses","M\xe9dicaments","Photographiez le compte rendu complet avec une bonne lumi\xe8re. Masquez si possible le nom et les donn\xe9es personnelles.","Expliquer les r\xe9sultats","M\xe9dicaments et doses","Exemple : metformine 500 mg, \xe9nalapril 10 mg...","Contexte suppl\xe9mentaire","Allergies, reins/foie, grossesse...","V\xe9rifier la compatibilit\xe9","Important : AI peut se tromper. Ce n\u2019est pas un diagnostic ni une prescription. Ne changez pas les m\xe9dicaments ou doses sans m\xe9decin. En cas de sympt\xf4mes dangereux, appelez les urgences.","La photo d\u2019analyse appara\xeetra ici"],t.w)
B.agm=new A.n(B.at,["An\xe1lisis","Medicamentos","Fotograf\xede todo el informe de laboratorio con buena luz. Oculte el nombre y otros datos personales si es posible.","Explicar resultados","Medicamentos y dosis","Ejemplo: metformina 500 mg, enalapril 10 mg...","Informaci\xf3n adicional","Alergias, ri\xf1\xf3n/h\xedgado, embarazo...","Comprobar compatibilidad","Importante: AI puede equivocarse. No es un diagn\xf3stico ni una receta. No cambie medicamentos o dosis sin un m\xe9dico. Ante s\xedntomas peligrosos llame a emergencias.","La foto del an\xe1lisis aparecer\xe1 aqu\xed"],t.w)
B.agi=new A.n(B.at,["Analisi","Farmaci","Fotografa tutto il referto con buona luce. Se possibile nascondi nome e dati personali.","Spiega i risultati","Farmaci e dosaggi","Esempio: metformina 500 mg, enalapril 10 mg...","Contesto aggiuntivo","Allergie, reni/fegato, gravidanza...","Verifica compatibilit\xe0","Importante: AI pu\xf2 sbagliare. Non \xe8 una diagnosi n\xe9 una prescrizione. Non cambiare farmaci o dosi senza medico. In caso di sintomi pericolosi chiama l\u2019emergenza.","La foto dell\u2019analisi apparir\xe0 qui"],t.w)
B.agh=new A.n(B.at,["Badania","Leki","Zr\xf3b zdj\u0119cie ca\u0142ego wyniku badania w dobrym \u015bwietle. Je\u015bli mo\u017cna, zakryj imi\u0119 i dane osobowe.","Wyja\u015bnij wyniki","Leki i dawkowanie","Przyk\u0142ad: metformina 500 mg, enalapryl 10 mg...","Dodatkowo","Alergie, nerki/w\u0105troba, ci\u0105\u017ca...","Sprawd\u017a zgodno\u015b\u0107","Wa\u017cne: AI mo\u017ce si\u0119 myli\u0107. To nie jest diagnoza ani zalecenie leczenia. Nie zmieniaj lek\xf3w ani dawek bez lekarza. Przy gro\u017anych objawach dzwo\u0144 po pomoc.","Zdj\u0119cie badania pojawi si\u0119 tutaj"],t.w)
B.agb=new A.n(B.at,["An\xe1lises","Medicamentos","Fotografe o relat\xf3rio completo com boa luz. Se poss\xedvel, oculte nome e dados pessoais.","Explicar resultados","Medicamentos e doses","Exemplo: metformina 500 mg, enalapril 10 mg...","Contexto adicional","Alergias, rins/f\xedgado, gravidez...","Verificar compatibilidade","Importante: AI pode errar. Isto n\xe3o \xe9 diagn\xf3stico nem prescri\xe7\xe3o. N\xe3o altere medicamentos ou doses sem m\xe9dico. Em sintomas perigosos, ligue para emerg\xeancia.","A foto da an\xe1lise aparecer\xe1 aqui"],t.w)
B.agg=new A.n(B.at,["Labuitslagen","Medicijnen","Fotografeer het hele labrapport bij goed licht. Verberg indien mogelijk naam en persoonlijke gegevens.","Resultaten uitleggen","Medicijnen en doseringen","Voorbeeld: metformine 500 mg, enalapril 10 mg...","Extra context","Allergie\xebn, nier/lever, zwangerschap...","Compatibiliteit controleren","Belangrijk: AI kan fouten maken. Dit is geen diagnose of behandeladvies. Verander geen medicijnen of doseringen zonder arts. Bel hulpdiensten bij gevaarlijke symptomen.","Labfoto verschijnt hier"],t.w)
B.ag6=new A.n(B.at,["Analize","Medicamente","Fotografia\u021bi \xeentregul buletin de analize \xeen lumin\u0103 bun\u0103. Dac\u0103 se poate, ascunde\u021bi numele \u0219i datele personale.","Explic\u0103 rezultatele","Medicamente \u0219i doze","Exemplu: metformin 500 mg, enalapril 10 mg...","Context suplimentar","Alergii, rinichi/ficat, sarcin\u0103...","Verific\u0103 compatibilitatea","Important: AI poate gre\u0219i. Nu este diagnostic sau prescrip\u021bie. Nu schimba\u021bi medicamentele ori dozele f\u0103r\u0103 medic. La simptome periculoase suna\u021bi la urgen\u021b\u0103.","Fotografia analizei va ap\u0103rea aici"],t.w)
B.agk=new A.n(B.at,["V\xfdsledky","L\xe9ky","Vyfo\u0165te cel\xfd laboratorn\xed v\xfdsledek v dobr\xe9m sv\u011btle. Pokud mo\u017eno zakryjte jm\xe9no a osobn\xed \xfadaje.","Vysv\u011btlit v\xfdsledky","L\xe9ky a d\xe1vkov\xe1n\xed","P\u0159\xedklad: metformin 500 mg, enalapril 10 mg...","Dopl\u0148uj\xedc\xed \xfadaje","Alergie, ledviny/j\xe1tra, t\u011bhotenstv\xed...","Zkontrolovat kompatibilitu","D\u016fle\u017eit\xe9: AI se m\u016f\u017ee m\xfdlit. Nen\xed to diagn\xf3za ani l\xe9\u010debn\xe9 doporu\u010den\xed. Nem\u011b\u0148te l\xe9ky ani d\xe1vky bez l\xe9ka\u0159e. P\u0159i nebezpe\u010dn\xfdch p\u0159\xedznac\xedch volejte z\xe1chranku.","Fotka v\xfdsledku se zobraz\xed zde"],t.w)
B.ago=new A.n(B.at,["V\xfdsledky","Lieky","Odfo\u0165te cel\xfd laborat\xf3rny v\xfdsledok pri dobrom svetle. Ak je mo\u017en\xe9, zakryte meno a osobn\xe9 \xfadaje.","Vysvetli\u0165 v\xfdsledky","Lieky a d\xe1vkovanie","Pr\xedklad: metform\xedn 500 mg, enalapril 10 mg...","Dopl\u0148uj\xface \xfadaje","Alergie, obli\u010dky/pe\u010de\u0148, tehotenstvo...","Skontrolova\u0165 kompatibilitu","D\xf4le\u017eit\xe9: AI sa m\xf4\u017ee m\xfdli\u0165. Nie je to diagn\xf3za ani lie\u010debn\xe9 odpor\xfa\u010danie. Neme\u0148te lieky ani d\xe1vky bez lek\xe1ra. Pri nebezpe\u010dn\xfdch pr\xedznakoch volajte z\xe1chranku.","Fotka v\xfdsledku sa zobraz\xed tu"],t.w)
B.aga=new A.n(B.at,["Leletek","Gy\xf3gyszerek","F\xe9nyk\xe9pezze le a teljes laborleletet j\xf3 f\xe9nyben. Lehet\u0151leg takarja ki a nevet \xe9s szem\xe9lyes adatokat.","Eredm\xe9nyek magyar\xe1zata","Gy\xf3gyszerek \xe9s adagok","P\xe9lda: metformin 500 mg, enalapril 10 mg...","Tov\xe1bbi adatok","Allergi\xe1k, vese/m\xe1j, terhess\xe9g...","Kompatibilit\xe1s ellen\u0151rz\xe9se","Fontos: az AI t\xe9vedhet. Ez nem diagn\xf3zis \xe9s nem kezel\xe9si javaslat. Ne v\xe1ltoztasson gy\xf3gyszert vagy adagot orvos n\xe9lk\xfcl. Vesz\xe9lyes t\xfcnetekn\xe9l h\xedvjon s\xfcrg\u0151ss\xe9gi seg\xedts\xe9get.","A lelet fot\xf3ja itt jelenik meg"],t.w)
B.ag8=new A.n(B.at,["Provsvar","L\xe4kemedel","Fotografera hela provsvaret i bra ljus. D\xf6lj om m\xf6jligt namn och personuppgifter.","F\xf6rklara resultat","L\xe4kemedel och doser","Exempel: metformin 500 mg, enalapril 10 mg...","Ytterligare information","Allergier, njure/lever, graviditet...","Kontrollera kompatibilitet","Viktigt: AI kan ha fel. Detta \xe4r ingen diagnos eller ordination. \xc4ndra inte l\xe4kemedel eller doser utan l\xe4kare. Ring akut hj\xe4lp vid farliga symtom.","Foto av provsvaret visas h\xe4r"],t.w)
B.agl=new A.n(B.at,["Pr\xf8ver","Medicin","Fotograf\xe9r hele laboratoriesvaret i godt lys. Skjul om muligt navn og persondata.","Forklar resultater","Medicin og doser",u.Z,"Yderligere info","Allergier, nyre/lever, graviditet...","Tjek kompatibilitet","Vigtigt: AI kan tage fejl. Dette er ikke diagnose eller behandling. \xc6ndr ikke medicin eller doser uden l\xe6ge. Ring akut ved farlige symptomer.","Foto af pr\xf8ven vises her"],t.w)
B.ag4=new A.n(B.at,["Kokeet","L\xe4\xe4kkeet","Kuvaa koko laboratoriotulos hyv\xe4ss\xe4 valossa. Peit\xe4 nimi ja henkil\xf6tiedot jos mahdollista.","Selit\xe4 tulokset","L\xe4\xe4kkeet ja annokset","Esim.: metformiini 500 mg, enalapriili 10 mg...","Lis\xe4tiedot","Allergiat, munuaiset/maksa, raskaus...","Tarkista yhteensopivuus","T\xe4rke\xe4\xe4: AI voi erehty\xe4. T\xe4m\xe4 ei ole diagnoosi eik\xe4 hoitom\xe4\xe4r\xe4ys. \xc4l\xe4 muuta l\xe4\xe4kkeit\xe4 tai annoksia ilman l\xe4\xe4k\xe4ri\xe4. Vaarallisissa oireissa soita h\xe4t\xe4numeroon.","Kuva kokeesta n\xe4kyy t\xe4ss\xe4"],t.w)
B.agd=new A.n(B.at,["Pr\xf8ver","Medisiner","Fotografer hele pr\xf8vesvaret i godt lys. Skjul navn og persondata hvis mulig.","Forklar resultater","Medisiner og doser",u.Z,"Tilleggsinfo","Allergier, nyre/lever, graviditet...","Sjekk kompatibilitet","Viktig: AI kan ta feil. Dette er ikke diagnose eller behandling. Ikke endre medisiner eller doser uten lege. Ring n\xf8dhjelp ved farlige symptomer.","Foto av pr\xf8ven vises her"],t.w)
B.agc=new A.n(B.at,["\u0395\u03be\u03b5\u03c4\u03ac\u03c3\u03b5\u03b9\u03c2","\u03a6\u03ac\u03c1\u03bc\u03b1\u03ba\u03b1","\u03a6\u03c9\u03c4\u03bf\u03b3\u03c1\u03b1\u03c6\u03af\u03c3\u03c4\u03b5 \u03bf\u03bb\u03cc\u03ba\u03bb\u03b7\u03c1\u03bf \u03c4\u03bf \u03b5\u03c1\u03b3\u03b1\u03c3\u03c4\u03b7\u03c1\u03b9\u03b1\u03ba\u03cc \u03ad\u03bd\u03c4\u03c5\u03c0\u03bf \u03bc\u03b5 \u03ba\u03b1\u03bb\u03cc \u03c6\u03c9\u03c4\u03b9\u03c3\u03bc\u03cc. \u039a\u03c1\u03cd\u03c8\u03c4\u03b5 \u03b1\u03bd \u03bc\u03c0\u03bf\u03c1\u03b5\u03af\u03c4\u03b5 \u03cc\u03bd\u03bf\u03bc\u03b1 \u03ba\u03b1\u03b9 \u03c0\u03c1\u03bf\u03c3\u03c9\u03c0\u03b9\u03ba\u03ac \u03b4\u03b5\u03b4\u03bf\u03bc\u03ad\u03bd\u03b1.","\u0395\u03be\u03ae\u03b3\u03b7\u03c3\u03b7 \u03b1\u03c0\u03bf\u03c4\u03b5\u03bb\u03b5\u03c3\u03bc\u03ac\u03c4\u03c9\u03bd","\u03a6\u03ac\u03c1\u03bc\u03b1\u03ba\u03b1 \u03ba\u03b1\u03b9 \u03b4\u03cc\u03c3\u03b5\u03b9\u03c2","\u03a0\u03b1\u03c1\u03ac\u03b4\u03b5\u03b9\u03b3\u03bc\u03b1: \u03bc\u03b5\u03c4\u03c6\u03bf\u03c1\u03bc\u03af\u03bd\u03b7 500 mg, \u03b5\u03bd\u03b1\u03bb\u03b1\u03c0\u03c1\u03af\u03bb\u03b7 10 mg...","\u03a0\u03c1\u03cc\u03c3\u03b8\u03b5\u03c4\u03b1 \u03c3\u03c4\u03bf\u03b9\u03c7\u03b5\u03af\u03b1","\u0391\u03bb\u03bb\u03b5\u03c1\u03b3\u03af\u03b5\u03c2, \u03bd\u03b5\u03c6\u03c1\u03ac/\u03ae\u03c0\u03b1\u03c1, \u03b5\u03b3\u03ba\u03c5\u03bc\u03bf\u03c3\u03cd\u03bd\u03b7...","\u0388\u03bb\u03b5\u03b3\u03c7\u03bf\u03c2 \u03c3\u03c5\u03bc\u03b2\u03b1\u03c4\u03cc\u03c4\u03b7\u03c4\u03b1\u03c2","\u03a3\u03b7\u03bc\u03b1\u03bd\u03c4\u03b9\u03ba\u03cc: \u03c4\u03bf AI \u03bc\u03c0\u03bf\u03c1\u03b5\u03af \u03bd\u03b1 \u03ba\u03ac\u03bd\u03b5\u03b9 \u03bb\u03ac\u03b8\u03b7. \u0394\u03b5\u03bd \u03b5\u03af\u03bd\u03b1\u03b9 \u03b4\u03b9\u03ac\u03b3\u03bd\u03c9\u03c3\u03b7 \u03ae \u03b8\u03b5\u03c1\u03b1\u03c0\u03b5\u03c5\u03c4\u03b9\u03ba\u03ae \u03bf\u03b4\u03b7\u03b3\u03af\u03b1. \u039c\u03b7\u03bd \u03b1\u03bb\u03bb\u03ac\u03b6\u03b5\u03c4\u03b5 \u03c6\u03ac\u03c1\u03bc\u03b1\u03ba\u03b1 \u03ae \u03b4\u03cc\u03c3\u03b5\u03b9\u03c2 \u03c7\u03c9\u03c1\u03af\u03c2 \u03b3\u03b9\u03b1\u03c4\u03c1\u03cc. \u03a3\u03b5 \u03b5\u03c0\u03b9\u03ba\u03af\u03bd\u03b4\u03c5\u03bd\u03b1 \u03c3\u03c5\u03bc\u03c0\u03c4\u03ce\u03bc\u03b1\u03c4\u03b1 \u03ba\u03b1\u03bb\u03ad\u03c3\u03c4\u03b5 \u03b5\u03c0\u03b5\u03af\u03b3\u03bf\u03bd\u03c4\u03b1.","\u0397 \u03c6\u03c9\u03c4\u03bf\u03b3\u03c1\u03b1\u03c6\u03af\u03b1 \u03b5\u03be\u03ad\u03c4\u03b1\u03c3\u03b7\u03c2 \u03b8\u03b1 \u03b5\u03bc\u03c6\u03b1\u03bd\u03b9\u03c3\u03c4\u03b5\u03af \u03b5\u03b4\u03ce"],t.w)
B.ag2=new A.n(B.at,["Tahliller","\u0130la\xe7lar","Laboratuvar raporunun tamam\u0131n\u0131 iyi \u0131\u015f\u0131kta foto\u011fraflay\u0131n. M\xfcmk\xfcnse ad ve ki\u015fisel verileri kapat\u0131n.","Sonu\xe7lar\u0131 a\xe7\u0131kla","\u0130la\xe7lar ve dozlar","\xd6rnek: metformin 500 mg, enalapril 10 mg...","Ek bilgi","Alerjiler, b\xf6brek/karaci\u011fer, hamilelik...","Uyumlulu\u011fu kontrol et","\xd6nemli: AI hata yapabilir. Bu tan\u0131 veya tedavi re\xe7etesi de\u011fildir. Doktor olmadan ila\xe7lar\u0131 veya dozlar\u0131 de\u011fi\u015ftirmeyin. Tehlikeli belirtilerde acili aray\u0131n.","Tahlil foto\u011fraf\u0131 burada g\xf6r\xfcnecek"],t.w)
B.agp=new A.n(B.at,["\u0418\u0437\u0441\u043b\u0435\u0434\u0432\u0430\u043d\u0438\u044f","\u041b\u0435\u043a\u0430\u0440\u0441\u0442\u0432\u0430","\u0421\u043d\u0438\u043c\u0430\u0439\u0442\u0435 \u0446\u0435\u043b\u0438\u044f \u043b\u0430\u0431\u043e\u0440\u0430\u0442\u043e\u0440\u0435\u043d \u0440\u0435\u0437\u0443\u043b\u0442\u0430\u0442 \u043f\u0440\u0438 \u0434\u043e\u0431\u0440\u0430 \u0441\u0432\u0435\u0442\u043b\u0438\u043d\u0430. \u0410\u043a\u043e \u0435 \u0432\u044a\u0437\u043c\u043e\u0436\u043d\u043e, \u0441\u043a\u0440\u0438\u0439\u0442\u0435 \u0438\u043c\u0435 \u0438 \u043b\u0438\u0447\u043d\u0438 \u0434\u0430\u043d\u043d\u0438.","\u041e\u0431\u044f\u0441\u043d\u0438 \u0440\u0435\u0437\u0443\u043b\u0442\u0430\u0442\u0438\u0442\u0435","\u041b\u0435\u043a\u0430\u0440\u0441\u0442\u0432\u0430 \u0438 \u0434\u043e\u0437\u0438",u.x,"\u0414\u043e\u043f\u044a\u043b\u043d\u0438\u0442\u0435\u043b\u043d\u043e","\u0410\u043b\u0435\u0440\u0433\u0438\u0438, \u0431\u044a\u0431\u0440\u0435\u0446\u0438/\u0447\u0435\u0440\u0435\u043d \u0434\u0440\u043e\u0431, \u0431\u0440\u0435\u043c\u0435\u043d\u043d\u043e\u0441\u0442...","\u041f\u0440\u043e\u0432\u0435\u0440\u0438 \u0441\u044a\u0432\u043c\u0435\u0441\u0442\u0438\u043c\u043e\u0441\u0442","\u0412\u0430\u0436\u043d\u043e: AI \u043c\u043e\u0436\u0435 \u0434\u0430 \u0433\u0440\u0435\u0448\u0438. \u0422\u043e\u0432\u0430 \u043d\u0435 \u0435 \u0434\u0438\u0430\u0433\u043d\u043e\u0437\u0430 \u0438\u043b\u0438 \u043d\u0430\u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435. \u041d\u0435 \u043f\u0440\u043e\u043c\u0435\u043d\u044f\u0439\u0442\u0435 \u043b\u0435\u043a\u0430\u0440\u0441\u0442\u0432\u0430 \u0438\u043b\u0438 \u0434\u043e\u0437\u0438 \u0431\u0435\u0437 \u043b\u0435\u043a\u0430\u0440. \u041f\u0440\u0438 \u043e\u043f\u0430\u0441\u043d\u0438 \u0441\u0438\u043c\u043f\u0442\u043e\u043c\u0438 \u043f\u043e\u0442\u044a\u0440\u0441\u0435\u0442\u0435 \u0441\u043f\u0435\u0448\u043d\u0430 \u043f\u043e\u043c\u043e\u0449.","\u0421\u043d\u0438\u043c\u043a\u0430\u0442\u0430 \u043d\u0430 \u0438\u0437\u0441\u043b\u0435\u0434\u0432\u0430\u043d\u0435\u0442\u043e \u0449\u0435 \u0441\u0435 \u043f\u043e\u044f\u0432\u0438 \u0442\u0443\u043a"],t.w)
B.ag1=new A.n(B.at,["Nalazi","Lijekovi","Fotografirajte cijeli laboratorijski nalaz pri dobrom svjetlu. Po mogu\u0107nosti sakrijte ime i osobne podatke.","Objasni rezultate","Lijekovi i doze","Primjer: metformin 500 mg, enalapril 10 mg...","Dodatno","Alergije, bubrezi/jetra, trudno\u0107a...","Provjeri kompatibilnost","Va\u017eno: AI mo\u017ee pogrije\u0161iti. Ovo nije dijagnoza ni terapijska preporuka. Ne mijenjajte lijekove ili doze bez lije\u010dnika. Kod opasnih simptoma zovite hitnu.","Fotografija nalaza pojavit \u0107e se ovdje"],t.w)
B.agn=new A.n(B.at,["Izvidi","Zdravila","Fotografirajte celoten laboratorijski izvid pri dobri svetlobi. Po mo\u017enosti skrijte ime in osebne podatke.","Pojasni rezultate","Zdravila in odmerki","Primer: metformin 500 mg, enalapril 10 mg...","Dodatno","Alergije, ledvice/jetra, nose\u010dnost...","Preveri zdru\u017eljivost","Pomembno: AI se lahko zmoti. To ni diagnoza ali navodilo za zdravljenje. Ne spreminjajte zdravil ali odmerkov brez zdravnika. Pri nevarnih simptomih pokli\u010dite nujno pomo\u010d.","Fotografija izvida bo prikazana tukaj"],t.w)
B.afY=new A.n(B.at,["Tyrimai","Vaistai","Nufotografuokite vis\u0105 tyrimo lap\u0105 geroje \u0161viesoje. Jei \u012fmanoma, pasl\u0117pkite vard\u0105 ir asmens duomenis.","Paai\u0161kinti rezultatus","Vaistai ir doz\u0117s","Pvz.: metforminas 500 mg, enalaprilis 10 mg...","Papildomai","Alergijos, inkstai/kepenys, n\u0117\u0161tumas...","Tikrinti suderinamum\u0105","Svarbu: AI gali klysti. Tai n\u0117ra diagnoz\u0117 ar gydymo paskyrimas. Nekeiskite vaist\u0173 ar dozi\u0173 be gydytojo. Esant pavojingiems simptomams kvieskite pagalb\u0105.","Tyrimo nuotrauka bus \u010dia"],t.w)
B.ag3=new A.n(B.at,["Anal\u012bzes","Z\u0101les","Nofotograf\u0113jiet visu anal\u012b\u017eu lapu lab\u0101 apgaismojum\u0101. Ja iesp\u0113jams, aizsedziet v\u0101rdu un personas datus.","Izskaidrot rezult\u0101tus","Z\u0101les un devas","Piem\u0113ram: metform\u012bns 500 mg, enalaprils 10 mg...","Papildus","Aler\u0123ijas, nieres/aknas, gr\u016btniec\u012bba...","P\u0101rbaud\u012bt sader\u012bbu","Svar\u012bgi: AI var k\u013c\u016bd\u012bties. T\u0101 nav diagnoze vai \u0101rst\u0113\u0161anas noz\u012bm\u0113jums. Nemainiet z\u0101les vai devas bez \u0101rsta. B\u012bstamu simptomu gad\u012bjum\u0101 zvaniet neatliekamajai pal\u012bdz\u012bbai.","Anal\u012bzes foto par\u0101d\u012bsies \u0161eit"],t.w)
B.ag7=new A.n(B.at,["Anal\xfc\xfcsid","Ravimid","Pildistage kogu laboritulemus heas valguses. V\xf5imalusel peitke nimi ja isikuandmed.","Selgita tulemusi","Ravimid ja annused","N\xe4ide: metformiin 500 mg, enalapriil 10 mg...","Lisainfo","Allergiad, neerud/maks, rasedus...","Kontrolli sobivust","T\xe4htis: AI v\xf5ib eksida. See ei ole diagnoos ega ravisoovitus. \xc4rge muutke ravimeid ega annuseid ilma arstita. Ohtlike s\xfcmptomite korral kutsuge abi.","Anal\xfc\xfcsi foto ilmub siia"],t.w)
B.ag0=new A.n(B.at,["\u0410\u043d\u0430\u043b\u0438\u0437\u0435","\u041b\u0435\u043a\u043e\u0432\u0438","\u0421\u043b\u0438\u043a\u0430\u0458\u0442\u0435 \u0446\u0435\u043e \u043b\u0430\u0431\u043e\u0440\u0430\u0442\u043e\u0440\u0438\u0458\u0441\u043a\u0438 \u043d\u0430\u043b\u0430\u0437 \u043f\u0440\u0438 \u0434\u043e\u0431\u0440\u043e\u043c \u0441\u0432\u0435\u0442\u043b\u0443. \u041f\u043e \u043c\u043e\u0433\u0443\u045b\u043d\u043e\u0441\u0442\u0438 \u0441\u0430\u043a\u0440\u0438\u0458\u0442\u0435 \u0438\u043c\u0435 \u0438 \u043b\u0438\u0447\u043d\u0435 \u043f\u043e\u0434\u0430\u0442\u043a\u0435.","\u041e\u0431\u0458\u0430\u0441\u043d\u0438 \u0440\u0435\u0437\u0443\u043b\u0442\u0430\u0442\u0435","\u041b\u0435\u043a\u043e\u0432\u0438 \u0438 \u0434\u043e\u0437\u0435",u.x,"\u0414\u043e\u0434\u0430\u0442\u043d\u043e","\u0410\u043b\u0435\u0440\u0433\u0438\u0458\u0435, \u0431\u0443\u0431\u0440\u0435\u0437\u0438/\u0458\u0435\u0442\u0440\u0430, \u0442\u0440\u0443\u0434\u043d\u043e\u045b\u0430...","\u041f\u0440\u043e\u0432\u0435\u0440\u0438 \u043a\u043e\u043c\u043f\u0430\u0442\u0438\u0431\u0438\u043b\u043d\u043e\u0441\u0442","\u0412\u0430\u0436\u043d\u043e: AI \u043c\u043e\u0436\u0435 \u0434\u0430 \u043f\u043e\u0433\u0440\u0435\u0448\u0438. \u041e\u0432\u043e \u043d\u0438\u0458\u0435 \u0434\u0438\u0458\u0430\u0433\u043d\u043e\u0437\u0430 \u043d\u0438\u0442\u0438 \u0442\u0435\u0440\u0430\u043f\u0438\u0458\u0430. \u041d\u0435 \u043c\u0435\u045a\u0430\u0458\u0442\u0435 \u043b\u0435\u043a\u043e\u0432\u0435 \u0438\u043b\u0438 \u0434\u043e\u0437\u0435 \u0431\u0435\u0437 \u043b\u0435\u043a\u0430\u0440\u0430. \u041a\u043e\u0434 \u043e\u043f\u0430\u0441\u043d\u0438\u0445 \u0441\u0438\u043c\u043f\u0442\u043e\u043c\u0430 \u043f\u043e\u0437\u043e\u0432\u0438\u0442\u0435 \u0445\u0438\u0442\u043d\u0443 \u043f\u043e\u043c\u043e\u045b.","\u0424\u043e\u0442\u043e\u0433\u0440\u0430\u0444\u0438\u0458\u0430 \u0430\u043d\u0430\u043b\u0438\u0437\u0435 \u045b\u0435 \u0431\u0438\u0442\u0438 \u043e\u0432\u0434\u0435"],t.w)
B.afZ=new A.n(B.at,["Analiza","Ila\xe7e","Fotografoni t\xeb gjith\xeb raportin laboratorik me drit\xeb t\xeb mir\xeb. N\xebse mundeni, fshihni emrin dhe t\xeb dh\xebnat personale.","Shpjego rezultatet","Ila\xe7e dhe doza","Shembull: metformin 500 mg, enalapril 10 mg...","Shtes\xeb","Alergji, veshka/m\xebl\xe7i, shtatz\xebni...","Kontrollo p\xebrputhshm\xebrin\xeb","E r\xebnd\xebsishme: AI mund t\xeb gaboj\xeb. Nuk \xebsht\xeb diagnoz\xeb apo recet\xeb. Mos ndryshoni ila\xe7e ose doza pa mjek. P\xebr simptoma t\xeb rrezikshme telefononi urgjenc\xebn.","Fotoja e analiz\xebs do t\xeb shfaqet k\xebtu"],t.w)
B.ag9=new A.n(B.at,["\u0410\u043d\u0430\u043b\u0438\u0437\u0438","\u041b\u0435\u043a\u043e\u0432\u0438","\u0424\u043e\u0442\u043e\u0433\u0440\u0430\u0444\u0438\u0440\u0430\u0458\u0442\u0435 \u0433\u043e \u0446\u0435\u043b\u0438\u043e\u0442 \u043b\u0430\u0431\u043e\u0440\u0430\u0442\u043e\u0440\u0438\u0441\u043a\u0438 \u0440\u0435\u0437\u0443\u043b\u0442\u0430\u0442 \u043f\u0440\u0438 \u0434\u043e\u0431\u0440\u0430 \u0441\u0432\u0435\u0442\u043b\u0438\u043d\u0430. \u0410\u043a\u043e \u0435 \u043c\u043e\u0436\u043d\u043e, \u0441\u043a\u0440\u0438\u0458\u0442\u0435 \u0438\u043c\u0435 \u0438 \u043b\u0438\u0447\u043d\u0438 \u043f\u043e\u0434\u0430\u0442\u043e\u0446\u0438.","\u041e\u0431\u0458\u0430\u0441\u043d\u0438 \u0440\u0435\u0437\u0443\u043b\u0442\u0430\u0442\u0438","\u041b\u0435\u043a\u043e\u0432\u0438 \u0438 \u0434\u043e\u0437\u0438",u.x,"\u0414\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u043d\u043e","\u0410\u043b\u0435\u0440\u0433\u0438\u0438, \u0431\u0443\u0431\u0440\u0435\u0437\u0438/\u0446\u0440\u043d \u0434\u0440\u043e\u0431, \u0431\u0440\u0435\u043c\u0435\u043d\u043e\u0441\u0442...","\u041f\u0440\u043e\u0432\u0435\u0440\u0438 \u043a\u043e\u043c\u043f\u0430\u0442\u0438\u0431\u0438\u043b\u043d\u043e\u0441\u0442","\u0412\u0430\u0436\u043d\u043e: AI \u043c\u043e\u0436\u0435 \u0434\u0430 \u043f\u043e\u0433\u0440\u0435\u0448\u0438. \u041e\u0432\u0430 \u043d\u0435 \u0435 \u0434\u0438\u0458\u0430\u0433\u043d\u043e\u0437\u0430 \u0438\u043b\u0438 \u0442\u0435\u0440\u0430\u043f\u0438\u0458\u0430. \u041d\u0435 \u043c\u0435\u043d\u0443\u0432\u0430\u0458\u0442\u0435 \u043b\u0435\u043a\u043e\u0432\u0438 \u0438\u043b\u0438 \u0434\u043e\u0437\u0438 \u0431\u0435\u0437 \u043b\u0435\u043a\u0430\u0440. \u041f\u0440\u0438 \u043e\u043f\u0430\u0441\u043d\u0438 \u0441\u0438\u043c\u043f\u0442\u043e\u043c\u0438 \u0458\u0430\u0432\u0435\u0442\u0435 \u0441\u0435 \u043d\u0430 \u0438\u0442\u043d\u0430 \u043f\u043e\u043c\u043e\u0448.","\u0424\u043e\u0442\u043e\u0433\u0440\u0430\u0444\u0438\u0458\u0430\u0442\u0430 \u043e\u0434 \u0430\u043d\u0430\u043b\u0438\u0437\u0430\u0442\u0430 \u045c\u0435 \u0431\u0438\u0434\u0435 \u0442\u0443\u043a\u0430"],t.w)
B.ag5=new A.n(B.at,["Pr\xf3f","Lyf","Taktu mynd af \xf6llu ranns\xf3knarbla\xf0inu \xed g\xf3\xf0ri birtu. Feldu nafn og pers\xf3nuuppl\xfdsingar ef h\xe6gt er.","\xdatsk\xfdra ni\xf0urst\xf6\xf0ur","Lyf og skammtar","D\xe6mi: metform\xedn 500 mg, enalapr\xedl 10 mg...","Vi\xf0b\xf3taruppl\xfdsingar","Ofn\xe6mi, n\xfdru/lifur, me\xf0ganga...","Athuga samh\xe6fni","Mikilv\xe6gt: AI getur haft rangt fyrir s\xe9r. \xdeetta er ekki greining e\xf0a me\xf0fer\xf0arfyrirm\xe6li. Breyttu ekki lyfjum e\xf0a sk\xf6mmtum \xe1n l\xe6knis. Hringdu \xed ney\xf0ara\xf0sto\xf0 vi\xf0 h\xe6ttuleg einkenni.","Mynd af pr\xf3fi birtist h\xe9r"],t.w)
